let authorizationStage='runtime';
try {
// Reuse MBW Admin's existing Access identity. Never trust a header without its signature.
authorizationStage='claims';
const input=$json,token=input.headers?.['cf-access-jwt-assertion'];
if(typeof token!=='string'||token.length>16384)throw new Error('Administrator sign-in required');
const parts=token.split('.');if(parts.length!==3)throw new Error('Invalid identity');
const decode=s=>Buffer.from(s,'base64url');
const header=JSON.parse(decode(parts[0]).toString()),claims=JSON.parse(decode(parts[1]).toString()),now=Math.floor(Date.now()/1000);
const issuer='https://tcfr-mbw.cloudflareaccess.com',audience='62ad79ee3af18f90b4827d5a84be038d4df901a56cbc21abda1ac5991ea89060';
if(header.alg!=='RS256'||typeof header.kid!=='string'||claims.iss!==issuer||!Array.isArray(claims.aud)||!claims.aud.includes(audience)||!Number.isFinite(claims.exp)||claims.exp<=now||(claims.nbf!==undefined&&(!Number.isFinite(claims.nbf)||claims.nbf>now))||typeof claims.email!=='string'||!claims.email.trim())throw new Error('Invalid identity');
authorizationStage='identity_service';
// Cloudflare's existing origin verifier checks the signature using Web Crypto.
// Send the same application token as the Access cookie so the edge authenticates too.
const identity=await this.helpers.httpRequest({url:'https://admin.mindobirdwatching.com/api/outcomes-identity',headers:{Cookie:'CF_Authorization='+token,'Cf-Access-Jwt-Assertion':token},json:true,timeout:10000});
if(identity?.authorized!==true)throw new Error('Invalid identity');
if(claims.email.trim().toLowerCase()==='faustoandrade635@gmail.com')throw new Error('Administrator access required');
authorizationStage='report';
const q=input.body||{};const valid=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;if(![q.start,q.end,q.priorStart,q.priorEnd].every(valid)||q.start>q.end||q.priorEnd>=q.start)throw Error('Invalid report');return [{json:{authorized:true,...q}}];}catch{return [{json:{authorized:false,ok:false,error:'Administrator authorization failed.'}}];}

const q=$('Authorize Administrator').first().json;
const props={"mindobirdwatching.com":"474681565","thecloudforestretreat.com":"449392042","experienceecuador.com":"516211767","mindotours.com":"555190853","chocoandinotours.com":"555387617","experiencetheamazon.com":"557349745","businessbuyingandselling.com":"525388203","eyesondanang.com":"557171133","arguellodentistry.com":"358273543"};
if(q.domain&&!Object.hasOwn(props,q.domain))throw Error('Invalid site');
const trendStart=new Date(Date.parse(q.end+'T00:00:00Z')-89*86400000).toISOString().slice(0,10);
const dates=[{startDate:q.start,endDate:q.end,name:'current'},{startDate:q.priorStart,endDate:q.priorEnd,name:'previous'}];
const excludedPath='^/(?:[a-z]{2}/)?(?:testing[0-9]*|admin|preview|staging|qa)(?:/|$).*';
const out=[];
for(const [domain,property] of Object.entries(props)){
 if(q.domain&&q.domain!==domain)continue;
 if(q.mode==='inspection'){
  const site=['experienceecuador.com','arguellodentistry.com'].includes(domain)?'https://'+domain+'/':'sc-domain:'+domain;
  if(!Array.isArray(q.pages)||q.pages.length<1||q.pages.length>3)throw Error('Invalid pages');
  for(const page of q.pages){const u=new URL(page);if(u.protocol!=='https:'||![domain,'www.'+domain].includes(u.hostname)||u.search||u.hash||u.username||u.password||u.port)throw Error('Invalid page');out.push({json:{domain,source:'inspection',page:u.href,url:'https://searchconsole.googleapis.com/v1/urlInspection/index:inspect',body:{inspectionUrl:u.href,siteUrl:site,languageCode:'en-US'}}});}continue;
 }
 const host={filter:{fieldName:'hostName',inListFilter:{values:[domain,'www.'+domain],caseSensitive:false}}};
 const filter=q.includeTests?host:{andGroup:{expressions:[host,{notExpression:{filter:{fieldName:'pagePath',stringFilter:{matchType:'FULL_REGEXP',value:excludedPath,caseSensitive:false}}}}]}};
 const report=(dimensions,metrics,dateRanges=dates,extra={})=>({dimensions:dimensions.map(name=>({name})),metrics:metrics.map(name=>({name})),dateRanges,dimensionFilter:filter,...extra});
 const descending=name=>[{metric:{metricName:name},desc:true}];
 const limited={orderBys:descending('sessions'),limit:'20'};
 const reports=q.domain?[
  report(['landingPage'],['sessions','engagedSessions'],dates,limited),
  report(['sessionSourceMedium'],['sessions','engagedSessions'],dates,limited),
  report(['sessionCampaignName'],['sessions','engagedSessions'],dates,limited),
  report(['country'],['sessions','engagedSessions'],dates,limited),
  report(['deviceCategory'],['sessions','engagedSessions'])
 ]:[
  report([],['sessions','engagedSessions']),
  report(['date'],['sessions'],[{startDate:trendStart,endDate:q.end}],{orderBys:[{dimension:{dimensionName:'date'}}],limit:'90'}),
  report(['sessionDefaultChannelGroup'],['sessions']),
  report(['pagePath'],['screenPageViews'],[dates[0]],{orderBys:descending('screenPageViews'),limit:'10'}),
  report(['eventName'],['eventCount'],dates,{limit:'1000'})
 ];
 out.push({json:{domain,source:q.domain?'gaDetails':'gaBatch',url:'https://analyticsdata.googleapis.com/v1beta/properties/'+property+':batchRunReports',body:{requests:reports}}});
 const site=['experienceecuador.com','arguellodentistry.com'].includes(domain)?'https://'+domain+'/':'sc-domain:'+domain;
 const url='https://www.googleapis.com/webmasters/v3/sites/'+encodeURIComponent(site)+'/searchAnalytics/query';
 const search=(source,body,prior=false)=>out.push({json:{domain,source,prior,url,body:{type:'web',dataState:'final',...body}}});
 if(q.domain){
  search('priorQueries',{startDate:q.priorStart,endDate:q.priorEnd,dimensions:['query'],rowLimit:1000});
  search('priorSearchPages',{startDate:q.priorStart,endDate:q.priorEnd,dimensions:['page'],rowLimit:1000});
  for(const dimension of ['country','device'])for(const prior of [false,true])search(dimension,{startDate:prior?q.priorStart:q.start,endDate:prior?q.priorEnd:q.end,dimensions:[dimension],rowLimit:250},prior);
 }else{
  search('search',{startDate:q.start,endDate:q.end});search('search',{startDate:q.priorStart,endDate:q.priorEnd},true);
  search('searchTrend',{startDate:trendStart,endDate:q.end,dimensions:['date'],rowLimit:90});
  search('queries',{startDate:q.start,endDate:q.end,dimensions:['query'],rowLimit:1000});
  search('searchPages',{startDate:q.start,endDate:q.end,dimensions:['page'],rowLimit:1000});
 }
}
return out;

const q=$('Authorize Administrator').first().json,contexts=$('Build report requests').all();
if(q.mode==='inspection'){const inspections=$input.all().map((item,i)=>{const context=contexts[i].json,result=item.json.inspectionResult?.indexStatusResult;return {url:context.page,status:result?'connected':'unavailable',verdict:result?.verdict??null,coverage:result?.coverageState??null,indexing:result?.indexingState??null,robots:result?.robotsTxtState??null,lastCrawl:result?.lastCrawlTime??null};});return [{json:{ok:true,version:3,inspection:true,start:q.start,end:q.end,updatedAt:new Date().toISOString(),sites:[{domain:q.domain,inspections}]}}];}
const domains=[...new Set(contexts.map(i=>i.json.domain))];
const sites=domains.map(domain=>({domain,...(!q.domain?{sessions:null,priorSessions:null,engagedSessions:null,priorEngagedSessions:null,search:null,priorSearch:null,trend:null,searchTrend:null,channels:null,pages:null,events:null,queries:null,searchPages:null,opportunities:null}:{landingPages:null,referrers:null,campaigns:null,analyticsCountries:null,analyticsDevices:null,priorQueries:null,priorSearchPages:null,searchCountries:null,priorSearchCountries:null,searchDevices:null,priorSearchDevices:null})}));
const value=(r,i)=>Number(r.metricValues?.[i]?.value||0);
const label=(r,i)=>r.dimensionValues?.[i]?.value;
const usable=r=>r&&Array.isArray(r.metricHeaders)&&!r.error;
const mapped=r=>(r.rows||[]).map(row=>Object.fromEntries([...(r.dimensionHeaders||[]).map((h,i)=>[h.name,label(row,i)]),...(r.metricHeaders||[]).map((h,i)=>[h.name,value(row,i)])]));
const grouped=r=>{if(!usable(r))return null;const map=new Map();for(const row of mapped(r)){const name=row[(r.dimensionHeaders||[]).find(h=>h.name!=='dateRange')?.name],prior=row.dateRange==='previous';if(!map.has(name))map.set(name,{name,sessions:0,priorSessions:0,engagedSessions:0,priorEngagedSessions:0});const x=map.get(name);x[prior?'priorSessions':'sessions']+=row.sessions||0;x[prior?'priorEngagedSessions':'engagedSessions']+=row.engagedSessions||0;}return [...map.values()].sort((a,b)=>b.sessions-a.sessions);};
const searchRows=rows=>rows.map(r=>({name:r.keys[0],clicks:r.clicks,impressions:r.impressions,ctr:r.ctr,position:r.position}));
for(const [i,item] of $input.all().entries()){
 const c=contexts[i]?.json;if(!c)continue;const p=item.json,s=sites.find(v=>v.domain===c.domain);if(!p||p.error)continue;
 if(c.source==='gaBatch'||c.source==='gaDetails'){
  if(!Array.isArray(p.reports)||p.reports.length!==5)continue;
  if(c.source==='gaDetails'){['landingPages','referrers','campaigns','analyticsCountries','analyticsDevices'].forEach((key,i)=>s[key]=grouped(p.reports[i]));}
  else{
   const [totals,trend,channels,pages,events]=p.reports;
   if(usable(totals)){for(const prior of [false,true]){const name=prior?'previous':'current';const r=(totals.rows||[]).find(r=>label(r,0)===name);s[prior?'priorSessions':'sessions']=r?value(r,0):0;s[prior?'priorEngagedSessions':'engagedSessions']=r?value(r,1):0;}}
   if(usable(trend))s.trend=(trend.rows||[]).map(r=>({date:label(r,0).replace(/^(\d{4})(\d{2})(\d{2})$/,'$1-$2-$3'),sessions:value(r,0)}));
   s.channels=grouped(channels);
   if(usable(pages))s.pages=(pages.rows||[]).map(r=>({path:label(r,0),views:value(r,0)}));
   if(usable(events)){const map=new Map();for(const r of mapped(events)){const name=r.eventName;if(!map.has(name))map.set(name,{name,count:0,priorCount:0});map.get(name)[r.dateRange==='previous'?'priorCount':'count']+=r.eventCount||0;}s.events=[...map.values()];}
  }
  s.analyticsCaveats=p.reports.some(r=>r.metadata?.subjectToThresholding||r.metadata?.dataLossFromOtherRow||r.metadata?.samplingMetadatas?.length)?'Google applied privacy thresholds, row limits or sampling; some detail may be omitted.':null;
 }else{
  if(!Array.isArray(p.rows)&&Object.keys(p).length>0&&!('responseAggregationType' in p))continue;
  const rows=p.rows||[];
  if(c.source==='search'){const r=rows[0];s[c.prior?'priorSearch':'search']={impressions:r?.impressions||0,clicks:r?.clicks||0,position:r?.position??null};}
  if(c.source==='searchTrend')s.searchTrend=rows.map(r=>({date:r.keys[0],impressions:r.impressions,clicks:r.clicks}));
  if(['queries','priorQueries','searchPages','priorSearchPages'].includes(c.source)){s[c.source]=searchRows(rows);if(c.source.endsWith('Pages'))s[c.source].forEach(r=>{r.url=r.name;delete r.name});}
  if(c.source==='queries')s.opportunities=rows.filter(r=>r.impressions>=20&&((r.position>=8&&r.position<=20)||(r.impressions>=100&&r.ctr<.01))).sort((a,b)=>b.impressions-a.impressions).slice(0,5).map(r=>({name:r.keys[0],clicks:r.clicks,impressions:r.impressions,ctr:r.ctr,position:r.position,reason:r.position>=8&&r.position<=20?'Position 8–20':'CTR below 1%'}));
  if(c.source==='country')s[c.prior?'priorSearchCountries':'searchCountries']=searchRows(rows);
  if(c.source==='device')s[c.prior?'priorSearchDevices':'searchDevices']=searchRows(rows);
 }
}
const trendStart=new Date(Date.parse(q.end+'T00:00:00Z')-89*86400000).toISOString().slice(0,10);
return [{json:{ok:true,version:3,details:Boolean(q.domain),includeTests:Boolean(q.includeTests),start:q.start,end:q.end,priorStart:q.priorStart,priorEnd:q.priorEnd,trendStart,updatedAt:new Date().toISOString(),sites}}];
